<script setup>
import {computed,onMounted,onUnmounted,ref} from 'vue';
import {application,actions} from '../../js/app.js';
import {createUiCommand} from '../../js/application/ui-contract.js';
import KfeSwipeBar from './KfeSwipeBar.vue';
import './work-session.css';

const loading=ref(true),busy=ref(false),error=ref(''),notice=ref(''),lastAction=ref(null),now=ref(Date.now());
const model=ref(null),summary=ref(null),form=ref(null),endDayConfirm=ref(false);
const dayStartOdometer=ref(''),dayBusinessKm=ref(''),dayPersonalKm=ref('');
const personalStartOdometer=ref(''),personalBusinessKm=ref(''),personalPersonalKm=ref('');
const personalEndOdometer=ref(''),personalToll=ref(''),personalParking=ref('');
const shiftEndOdometer=ref(''),shiftToll=ref(''),shiftParking=ref(''),shiftTollIncluded=ref(false),shiftParkingIncluded=ref(false);
let timer;

const screenState=computed(()=>model.value?.state||'DAY_START');
const latestOdometer=computed(()=>model.value?.latestOdometer);
const dayStatus=computed(()=>model.value?.day?.status||'NOT_STARTED');
const activeShift=computed(()=>model.value?.shift?.active?model.value.shift:null);
const activeTrip=computed(()=>model.value?.trip?.active?model.value.trip:null);
const shiftElapsed=computed(()=>activeShift.value?.startedAt?Math.max(0,Math.floor((now.value-Date.parse(activeShift.value.startedAt))/1000)):0);
const tripElapsed=computed(()=>activeTrip.value?.startedAt?Math.max(0,Math.floor((now.value-Date.parse(activeTrip.value.startedAt))/1000)):0);
const shiftTripCount=computed(()=>activeShift.value?.tripCount||0);
const dayStartDifference=computed(()=>differenceFor(dayStartOdometer.value,latestOdometer.value));
const personalStartDifference=computed(()=>differenceFor(personalStartOdometer.value,latestOdometer.value));
const dayAllocationValid=computed(()=>allocationValid(dayStartDifference.value,dayBusinessKm.value,dayPersonalKm.value));
const personalAllocationValid=computed(()=>allocationValid(personalStartDifference.value,personalBusinessKm.value,personalPersonalKm.value));
const shiftEndValid=computed(()=>{const value=Number(shiftEndOdometer.value);return Number.isInteger(value)&&value>=0&&(!activeShift.value?.startOdometer||value>=Number(activeShift.value.startOdometer));});
const personalEndValid=computed(()=>{const value=Number(personalEndOdometer.value);return Number.isInteger(value)&&value>=0&&(!activeTrip.value?.startOdometer||value>=Number(activeTrip.value.startOdometer));});
const canStartDay=computed(()=>screenState.value==='DAY_START'&&dayStatus.value!=='COMPLETED');
const canEndDay=computed(()=>screenState.value==='DAY_READY'&&!activeShift.value&&!activeTrip.value&&dayStatus.value!=='COMPLETED');

function formatDuration(totalSeconds){const s=Math.max(0,Number(totalSeconds)||0);return [Math.floor(s/3600),Math.floor(s/60)%60,Math.floor(s)%60].map(v=>String(v).padStart(2,'0')).join(':');}
function formatMoney(paise){return `₹ ${(Number(paise||0)/100).toFixed(2)}`;}
function differenceFor(current,previous){const value=Number(current);const prior=previous==null?null:Number(previous);if(!Number.isInteger(value)||value<0)return {valid:false,difference:0,required:false};if(prior==null)return {valid:true,difference:0,required:false};if(value<prior)return {valid:false,difference:prior-value,required:false};return {valid:true,difference:value-prior,required:value!==prior};}
function allocationValid(diff,business,personal){if(!diff?.valid)return false;if(!diff.required)return true;const b=Number(business),p=Number(personal);return Number.isInteger(b)&&Number.isInteger(p)&&b>=0&&p>=0&&b+p===diff.difference;}
function setError(message){error.value=message;}
function clearError(){error.value='';}
function openForm(kind){clearError();form.value=kind;if(kind==='DAY_START')dayStartOdometer.value=latestOdometer.value==null?'':String(latestOdometer.value);if(kind==='PERSONAL_END')personalEndOdometer.value=latestOdometer.value==null?'':String(latestOdometer.value);if(kind==='SHIFT_END'){shiftEndOdometer.value='';shiftToll.value='';shiftParking.value='';shiftTollIncluded.value=false;shiftParkingIncluded.value=false;}}
function closeForm(){if(busy.value)return;form.value=null;clearError();}
async function load(){loading.value=true;clearError();try{model.value=await application.getWorkScreenState();summary.value=await application.workSummary();window.dispatchEvent(new CustomEvent('kfe:work-state-changed'));}catch(e){setError(String(e?.message||e));}finally{loading.value=false;}}
async function loadSummary(){try{summary.value=await application.workSummary();}catch(e){setError(String(e?.message||e));}}
function announce(message,action){notice.value=message;lastAction.value=action||null;if(navigator.vibrate)navigator.vibrate(16);clearTimeout(announce.timer);announce.timer=setTimeout(()=>{notice.value='';lastAction.value=null;},5000);}
function createWorkCommand(type,payload){if(type==='START_SHIFT')return createUiCommand('START_SHIFT',payload);if(type==='START_TRIP')return createUiCommand('START_TRIP',payload);if(type==='END_TRIP')return createUiCommand('END_TRIP',payload);if(type==='END_SHIFT')return createUiCommand('END_SHIFT',payload);if(type==='START_DAY')return createUiCommand('START_DAY',payload);if(type==='START_PERSONAL_TRIP')return createUiCommand('START_PERSONAL_TRIP',payload);if(type==='END_PERSONAL_TRIP')return createUiCommand('END_PERSONAL_TRIP',payload);if(type==='END_DAY')return createUiCommand('END_DAY',payload);return createUiCommand(type,payload);}
async function dispatch(type,payload){if(busy.value)return null;busy.value=true;clearError();try{const result=await actions.dispatch(createWorkCommand(type,payload));form.value=null;endDayConfirm.value=false;await load();return result;}catch(e){setError(String(e?.message||e));return null;}finally{busy.value=false;}}
async function confirmDayStart(){const current=Number(dayStartOdometer.value);if(!Number.isInteger(current)||current<0){setError('Enter the day-start odometer.');return;}const diff=differenceFor(dayStartOdometer.value,latestOdometer.value);if(!diff.valid){setError('Odometer cannot decrease.');return;}if(!allocationValid(diff,dayBusinessKm.value,dayPersonalKm.value)){setError(`Allocate exactly ${diff.difference} km between business and personal.`);return;}const result=await dispatch('START_DAY',{odometer:current,prefilledOdometer:latestOdometer.value,businessKm:diff.required?Number(dayBusinessKm.value):0,personalKm:diff.required?Number(dayPersonalKm.value):0,actionMode:'SWIPE',direction:'RIGHT'});if(result)announce('Day started safely',{type:'START_DAY',id:result.id});}
async function startPersonalTrip(){if(latestOdometer.value==null){setError('A latest authoritative odometer is required before starting a personal trip.');return;}const current=Number(latestOdometer.value);const result=await dispatch('START_PERSONAL_TRIP',{odometer:current,prefilledOdometer:current,businessKm:0,personalKm:0,actionMode:'SWIPE',direction:'LEFT'});if(result)announce('Personal trip started safely',{type:'START_PERSONAL_TRIP',id:result.id});}
async function startShift(){const result=await dispatch('START_SHIFT',{actionMode:'SWIPE',direction:'RIGHT'});if(result)announce('Shift started safely',{type:'START_SHIFT',id:result.id});}
async function startBusinessTrip(){const result=await dispatch('START_TRIP',{actionMode:'SWIPE',direction:'RIGHT'});if(result)announce('Trip started safely',{type:'START_TRIP',id:result.id});}
async function endBusinessTrip(){const result=await dispatch('END_TRIP',{id:activeTrip.value?.id,actionMode:'SWIPE',direction:'RIGHT'});if(result)announce('Trip saved safely',{type:'END_TRIP',id:result.id});}
async function confirmPersonalEnd(){const end=Number(personalEndOdometer.value);if(!Number.isInteger(end)||end<0){setError('End odometer is compulsory.');return;}if(!personalEndValid.value){setError('End odometer cannot be below the trip start odometer.');return;}const result=await dispatch('END_PERSONAL_TRIP',{id:activeTrip.value?.id,endOdometer:end,tollPaise:Math.round(Math.max(0,Number(personalToll.value)||0)*100),parkingPaise:Math.round(Math.max(0,Number(personalParking.value)||0)*100),actionMode:'SWIPE',direction:'RIGHT'});if(result)announce('Personal trip saved safely',{type:'END_PERSONAL_TRIP',id:result.id});}
async function confirmShiftEnd(){const end=Number(shiftEndOdometer.value);if(!Number.isInteger(end)||end<0){setError('End odometer is compulsory.');return;}if(!shiftEndValid.value){setError('End odometer cannot be below the shift start odometer.');return;}const result=await dispatch('END_SHIFT',{id:activeShift.value?.id,endOdometer:end,tollPaise:Math.round(Math.max(0,Number(shiftToll.value)||0)*100),parkingPaise:Math.round(Math.max(0,Number(shiftParking.value)||0)*100),tollIncludedInFare:shiftTollIncluded.value,parkingIncludedInFare:shiftParkingIncluded.value,actionMode:'SWIPE',direction:'RIGHT'});if(result)announce('Shift closed safely',{type:'END_SHIFT',id:result.id});}
async function confirmEndDay(){if(!canEndDay.value)return;const result=await dispatch('END_DAY',{actionMode:'BUTTON',direction:null});if(result)announce('Day ended safely',{type:'END_DAY',id:result.id});}
async function undoLast(){if(!lastAction.value||busy.value)return;const action=lastAction.value;const result=await dispatch('UNDO_WORK_ACTION',action);if(result)announce('Last action undone safely');}
function handleSwipe(action){if(action==='START_DAY')openForm('DAY_START');else if(action==='START_PERSONAL_TRIP')void startPersonalTrip();else if(action==='START_SHIFT')void startShift();else if(action==='START_TRIP')void startBusinessTrip();else if(action==='END_TRIP')void endBusinessTrip();else if(action==='END_PERSONAL_TRIP')openForm('PERSONAL_END');else if(action==='END_SHIFT')openForm('SHIFT_END');}
const canEndShiftButton=computed(()=>screenState.value==='SHIFT_WAITING');
function handleEndShiftButton(){if(canEndShiftButton.value)openForm('SHIFT_END');}
function requestEndDay(){if(canEndDay.value){clearError();void loadSummary();endDayConfirm.value=true;}}
function cancelEndDay(){if(busy.value)return;endDayConfirm.value=false;clearError();}
function onKey(event){if(event.key==='Escape'){if(endDayConfirm.value)cancelEndDay();else if(form.value)closeForm();}}
onMounted(()=>{timer=setInterval(()=>now.value=Date.now(),1000);window.addEventListener('keydown',onKey);void load();});
onUnmounted(()=>{clearInterval(timer);clearTimeout(announce.timer);window.removeEventListener('keydown',onKey);});
</script>
<template>
<section class="kfe-work-session" aria-labelledby="work-title">
  <div v-if="loading" class="work-loading" role="status">Loading Work…</div>
  <template v-else>
    <header class="work-header"><div><p class="kfe-eyebrow">Operational cockpit</p><h1 id="work-title">Work</h1><p>Today · {{ screenState.replaceAll('_',' ') }}</p></div><div class="work-header-status"><span v-if="activeShift" class="work-shift-mini">SHIFT {{ formatDuration(shiftElapsed) }}</span><span v-else class="work-shift-mini">SHIFT —</span></div></header>
    <div v-if="error" class="work-error" role="alert">{{ error }}</div>
    <div v-if="notice" class="work-notice" role="status"><span>✓ {{ notice }}</span><button v-if="lastAction" type="button" @click="undoLast">Undo</button></div>
    <main class="work-main">
      <section v-if="screenState==='DAY_START'||screenState==='DAY_ENDED'" class="work-state-panel day-start-panel"><p class="kfe-eyebrow">{{ screenState==='DAY_ENDED'?'DAY ENDED':'START OF DAY' }}</p><h2>{{ screenState==='DAY_ENDED'?'Ready for the next operational day':'Ready for operation' }}</h2><p class="muted">{{ latestOdometer==null?'Enter the odometer to establish the first authoritative reading.':'Your latest authoritative odometer is prefilled when you start the day.' }}</p></section>
      <section v-else-if="screenState==='DAY_READY'" class="work-state-panel ready-panel"><p class="kfe-eyebrow">READY FOR OPERATION</p><div class="ready-odometer"><span>Odometer</span><strong>{{ latestOdometer }}</strong><small>km</small></div><div class="ready-status"><span>Shift: <b>NOT ACTIVE</b></span><span>Personal trip: <b>NOT ACTIVE</b></span></div><button class="end-day-button" type="button" :disabled="busy||!canEndDay" @click="requestEndDay">End day</button></section>
      <section v-else-if="screenState==='SHIFT_WAITING'" class="work-state-panel waiting-panel"><p class="kfe-eyebrow">SHIFT ACTIVE</p><div class="waiting-metrics"><div><span>Trips</span><strong>{{ shiftTripCount }}</strong></div><div><span>Shift time</span><strong>{{ formatDuration(shiftElapsed) }}</strong></div></div><p class="waiting-copy">Waiting for the next ride.</p><button class="end-shift-button" type="button" @click="handleEndShiftButton">End shift</button></section>
      <section v-else-if="screenState==='BUSINESS_TRIP'" class="work-state-panel trip-panel"><p class="kfe-eyebrow">BUSINESS TRIP</p><div class="trip-timer" aria-label="Trip timer">{{ formatDuration(tripElapsed) }}</div><p class="muted">Trip active</p></section>
      <section v-else-if="screenState==='PERSONAL_TRIP'" class="work-state-panel trip-panel"><p class="kfe-eyebrow">PERSONAL TRIP</p><div class="trip-timer" aria-label="Personal trip timer">{{ formatDuration(tripElapsed) }}</div><p class="muted">Personal trip active</p></section>
    </main>
    <div class="bottom-action" aria-label="Work action">
      <KfeSwipeBar v-if="!form && screenState==='DAY_START'" left-label="START PERSONAL TRIP" right-label="START DAY" left-action="START_PERSONAL_TRIP" right-action="START_DAY" :disabled="busy" :right-disabled="!canStartDay" @swipe="handleSwipe" />
      <KfeSwipeBar v-else-if="!form && screenState==='DAY_ENDED'" left-label="START PERSONAL TRIP" right-label="START DAY" left-action="START_PERSONAL_TRIP" right-action="START_DAY" :disabled="busy" :right-disabled="true" @swipe="handleSwipe" />
      <KfeSwipeBar v-else-if="!form && screenState==='DAY_READY'" left-label="START PERSONAL TRIP" right-label="START SHIFT" left-action="START_PERSONAL_TRIP" right-action="START_SHIFT" :disabled="busy" @swipe="handleSwipe" />
      <KfeSwipeBar v-else-if="!form && screenState==='SHIFT_WAITING'" right-label="START TRIP" right-action="START_TRIP" :disabled="busy" @swipe="handleSwipe" />
      <KfeSwipeBar v-else-if="!form && screenState==='BUSINESS_TRIP'" right-label="END TRIP" right-action="END_TRIP" :disabled="busy" @swipe="handleSwipe" />
      <KfeSwipeBar v-else-if="!form && screenState==='PERSONAL_TRIP'" right-label="END PERSONAL TRIP" right-action="END_PERSONAL_TRIP" :disabled="busy" @swipe="handleSwipe" />
      <KfeSwipeBar v-else-if="form==='PERSONAL_END'" right-label="CLOSE PERSONAL TRIP" right-action="CLOSE_PERSONAL_TRIP" :disabled="busy||!personalEndValid" @swipe="handleSwipe" />
      <KfeSwipeBar v-else-if="form==='SHIFT_END'" right-label="CLOSE SHIFT" right-action="CLOSE_SHIFT" :disabled="busy||!shiftEndValid" @swipe="handleSwipe" />
    </div>
    <div v-if="form==='DAY_START'" class="work-form-overlay"><div class="work-form-card"><p class="kfe-eyebrow">START DAY</p><h2>Odometer</h2><label>Start odometer *<input v-model="dayStartOdometer" inputmode="numeric" type="number" min="0" step="1" autofocus /></label><p v-if="latestOdometer!=null" class="muted">Prefilled from the latest authoritative reading.</p><div v-if="dayStartDifference.required" class="allocation-block"><h3>Allocate {{ dayStartDifference.difference }} km</h3><p>Choose how the difference should be classified before the day starts.</p><label>Business KM<input v-model="dayBusinessKm" inputmode="numeric" type="number" min="0" step="1" /></label><label>Personal KM<input v-model="dayPersonalKm" inputmode="numeric" type="number" min="0" step="1" /></label></div><button class="primary-action" type="button" :disabled="busy||!dayStartDifference.valid||!dayAllocationValid" @click="confirmDayStart">Confirm</button><button class="secondary-action" type="button" :disabled="busy" @click="closeForm">Cancel</button></div></div>
    <div v-if="form==='PERSONAL_END'" class="work-form-overlay"><div class="work-form-card"><p class="kfe-eyebrow">END PERSONAL TRIP</p><h2>Trip closing details</h2><label>End odometer *<input v-model="personalEndOdometer" inputmode="numeric" type="number" min="0" step="1" autofocus /></label><label>Toll <span class="optional">Optional</span><input v-model="personalToll" inputmode="decimal" type="number" min="0" step="0.01" /></label><label>Parking <span class="optional">Optional</span><input v-model="personalParking" inputmode="decimal" type="number" min="0" step="0.01" /></label><p class="muted">End odometer is required. The trip cannot close without it.</p><button class="secondary-action" type="button" :disabled="busy" @click="closeForm">Cancel</button></div></div>
    <div v-if="form==='SHIFT_END'" class="work-form-overlay"><div class="work-form-card"><p class="kfe-eyebrow">END SHIFT</p><h2>Shift closing details</h2><label>End odometer *<input v-model="shiftEndOdometer" inputmode="numeric" type="number" min="0" step="1" autofocus /></label><div class="optional-row"><label>Toll <span class="optional">Optional</span><input v-model="shiftToll" inputmode="decimal" type="number" min="0" step="0.01" /></label><div class="choice-group"><span>Toll fare treatment</span><label><input v-model="shiftTollIncluded" type="radio" :value="true" /> Included in fare</label><label><input v-model="shiftTollIncluded" type="radio" :value="false" /> Not included in fare</label></div></div><div class="optional-row"><label>Parking <span class="optional">Optional</span><input v-model="shiftParking" inputmode="decimal" type="number" min="0" step="0.01" /></label><div class="choice-group"><span>Parking fare treatment</span><label><input v-model="shiftParkingIncluded" type="radio" :value="true" /> Included in fare</label><label><input v-model="shiftParkingIncluded" type="radio" :value="false" /> Not included in fare</label></div></div><p class="muted">End odometer is required and starts empty. Complete the form, then use the Close Shift swipe.</p><button class="secondary-action" type="button" :disabled="busy" @click="closeForm">Cancel</button></div></div>
    <div v-if="endDayConfirm" class="work-form-overlay"><div class="work-form-card" role="dialog" aria-modal="true" aria-labelledby="end-day-title"><p class="kfe-eyebrow">END DAY</p><h2 id="end-day-title">End today's work day?</h2><p class="muted">Odometer and revenue are already recorded. No additional entry is required.</p><div class="summary-grid"><div><span>Business trips</span><strong>{{ summary?.tripCount||0 }}</strong></div><div><span>Shifts</span><strong>{{ summary?.shiftCount||0 }}</strong></div><div><span>Revenue</span><strong>{{ formatMoney(summary?.revenuePaise||0) }}</strong></div><div><span>Shift time</span><strong>{{ formatDuration(summary?.shiftSeconds||0) }}</strong></div></div><button class="primary-action" type="button" :disabled="busy" @click="confirmEndDay">Confirm End Day</button><button class="secondary-action" type="button" :disabled="busy" @click="cancelEndDay">Cancel</button></div></div>
  </template>
</section>
</template>